INSERT INTO `itineraries` (id, slug, title, badge_text, location_label, destination_slug, duration_days, duration_nights, category, location_type, best_time, summary, overview, highlights, inclusions, featured, is_published, hero_image) VALUES
(1, 'kashmir-paradise-valley', 'Kashmir Valley of Serenity & Alpine Meadows', 'Heaven On Earth', 'Srinagar, Gulmarg & Pahalgam, India', 'jammu-and-kashmir', 6, 5, 'Alpine Getaway', 'DOMESTIC', 'Year-Round (Snow: Dec-Feb, Blossoms: Apr-Oct)', 'Drift on Dal Lake in heritage cedar houseboats, ride the world-highest Gulmarg Gondola over snow peaks, and stroll through Pahalgam pine valleys.', NULL, 'Heritage Carved Cedar Luxury Houseboat Stay on Dal Lake; Sunset Shikara Ride & Floating Flower / Spice Market; Gulmarg Gondola Cable Car Ride to Apharwat Peak (Phase 1 & 2); Pahalgam Betaab Valley, Aru Valley & Baisaran Pine Meadows; Mughal Gardens (Shalimar, Nishat Bagh & Chashme Shahi)', 'Houseboat & Premium Alpine Resort Accommodations; Daily Traditional Kashmiri Wazwan & Multi-Cuisine Meals; Private Shikara Rides & Gondola Phase 1 & 2 Priority Passes; Dedicated Private Heating-Equipped 4x4 / Luxury Vehicle; Experienced Local Kashmir Concierge & Heritage Guide', 1, 1, 'assets/images/itineraries/kashmir-paradise-valley/1.webp'),
(2, 'bali-island-paradise', 'Bali Tropical Temples & Island Romance', 'Island of Gods', 'Bali, Indonesia', 'bali', 6, 5, 'Island Romance', 'INTERNATIONAL', 'April to November', 'Experience the magic of Bali with lush Ubud rice terraces, clifftop Uluwatu sunsets, sacred temples, Nusa Penida island speedboat tours, and private pool villas.', NULL, 'Tegallalang Emerald Rice Terraces & Iconic Jungle Swing; Clifftop Uluwatu Temple & Sunset Fire Kecak Dance; Full-Day Nusa Penida Speedboat Tour (Kelingking & Angel Billabong); Ubud Sacred Monkey Forest & Traditional Artisan Villages; Jimbaran Bay Candlelit Seafood Beachside Dinner', 'Private Pool Villa & 5-Star Luxury Resort Stay; Daily Floating Breakfasts & Gourmet Dining; Speedboat Tickets to Nusa Penida with Local Island Guide; All Entry Permits, Monument Passes & Cultural Performances; Private Chauffeur-Driven Air-Conditioned Vehicle Throughout', 1, 1, 'assets/images/itineraries/bali-island-paradise/1.webp'),
(3, 'goa-coastal-escape', 'Goa Sunkissed Shores & Beach Serenity', 'Coastal Luxury', 'Goa, India', 'goa', 5, 4, 'Beach & Coastal', 'DOMESTIC', 'October to May', 'Immerse yourself in golden sands, Portuguese architecture, vibrant beach shacks, spice plantations, and romantic Mandovi river sunset cruises.', NULL, 'Private Mandovi River Sunset Luxury Cruise; Old Goa UNESCO Heritage Cathedrals & Fontainhas Latin Quarter; Excursion to Dudhsagar Waterfalls & Spice Plantation; Calangute, Baga & Anjuna Beachside Leisure & Water Sports; Curated Goan Seafood & Coastal Gourmet Dining', 'Luxury Beachfront Resort Accommodations; Daily Gourmet Breakfast & Chef Special Dinners; Private AC Vehicle Transfers & Guided Sightseeing; Complimentary Sunset Cruise Passes & Sightseeing Tickets; Dedicated Concierge & Holiday Coordinator', 1, 1, 'assets/images/itineraries/goa-coastal-escape/1.webp'),
(4, 'phuket-krabi-island-odyssey', 'Phuket & Krabi Emerald Waters & Island Odyssey', 'Andaman Paradise', 'Phuket & Krabi, Thailand', 'phuket', 6, 5, 'Island Adventure', 'INTERNATIONAL', 'November to May', 'Speed across turquoise Andaman waters to Phi Phi Islands, kayak through James Bond limestone sea caves, and unwind on powdery white beaches in Krabi.', NULL, 'Phi Phi Islands & Maya Bay Luxury Speedboat Island Tour; James Bond Island Sea Canoeing in Phang Nga Bay; Krabi 4-Islands Tour (Phra Nang Cave, Tup & Chicken Island); Phuket Big Buddha, Wat Chalong & Old Town Sino-Portuguese Walk; Sunset Beachfront Seafood Galas & Traditional Thai Massages', '5-Star Oceanfront Resort Accommodations in Phuket & Krabi; Daily American / Asian Buffet Breakfasts & Island Luncheons; Speedboat Island Tours with Snorkeling Gear & Marine Park Fees; Inter-City Private Coastal Transfers (Phuket to Krabi); Dedicated Thailand Travel Desk & Airport Chauffeur', 0, 1, 'assets/images/itineraries/phuket-krabi-island-odyssey/1.webp'),
(5, 'singapore-modern-extravaganza', 'Singapore Futuristic Gardens & Sentosa Escapade', 'Garden City', 'Singapore', 'singapore', 5, 4, 'City of Future', 'INTERNATIONAL', 'Year-Round Destination', 'Step into the future with Gardens by the Bay, Marina Bay Sands SkyPark observation deck, Universal Studios Singapore, and world-class Sentosa Island attractions.', NULL, 'Gardens by the Bay: Flower Dome, Cloud Forest & Supertree Light Show; Full-Day Universal Studios Singapore & Sentosa Cable Car Pass; Marina Bay Sands SkyPark 57th Floor Observation Deck; Night Safari Open-Air Tram Ride & Wildlife Encounters; Scenic Singapore River Cruise & Jewel Changi Rain Vortex', '5-Star Luxury Downtown Singapore Hotel Accommodations; Daily International Buffet Breakfasts; Universal Studios One-Day Unlimited Pass & Sentosa Cable Car; All Fast-Track Tickets to Gardens by the Bay & SkyPark; Private Airport Chauffeur Transfers & City Sightseeing', 0, 1, 'assets/images/itineraries/singapore-modern-extravaganza/1.webp'),
(6, 'manali-shimla-himalayan-escape', 'Manali & Shimla Himalayan Snow & Pine Escapade', 'Himalayan Splendour', 'Shimla & Manali, Himachal Pradesh, India', 'shimla', 6, 5, 'Mountain Adventure', 'DOMESTIC', 'Year-Round (Snow: Dec-Feb, Pleasant: Mar-Jun)', 'Escape to snow-clad Himalayan peaks, cross through the engineering marvel of Atal Tunnel, paraglide in Solang Valley, and unwind in luxury wooden chalets.', NULL, 'Atal Tunnel Crossing & Sissu Lahaul Valley Snow Excursion; Solang Valley Paragliding, Zorbing & Cable Car Adventures; Historic Shimla Mall Road, The Ridge & Christ Church Heritage; Hadimba Devi Temple, Vashisht Hot Springs & Old Manali Cafes; Kufri Snow Viewpoint & Scenic Apple Orchard Trails', 'Luxury Wooden Chalet & 5-Star Mountain Resort Accommodations; Daily Hearty Himalayan Breakfasts & Candlelit Dinners; Private All-Weather AC Vehicle with Experienced Hill Driver; Solang Valley & Atal Tunnel Special Entry Permits; Dedicated Himachal Travel Desk & Concierge Support', 0, 1, 'assets/images/itineraries/manali-shimla-himalayan-escape/1.webp'),
(7, 'maldives-turquoise-atolls', 'Maldives Turquoise Lagoons & Overwater Villas', 'Tropical Bliss', 'North Malé Atoll, Maldives', 'maldives', 5, 4, 'Overwater Luxury', 'INTERNATIONAL', 'November to April', 'Indulge in the ultimate tropical sanctuary featuring private glass-floor overwater villas, vibrant coral reefs, dolphin catamaran cruises, and world-class spa relaxation.', NULL, 'Iconic Overwater Villa with Private Sun Deck & Lagoon Staircase; Scenic Speedboat / Seaplane Island Transfers; Guided Coral Reef Snorkeling with Sea Turtles & Manta Rays; Romantic Sunset Dolphin Cruise with Champagne & Canapés; Undersea Dining & Rejuvenating Hydrotherapy Spa Sessions', 'Luxury 5-Star Private Island Resort Villa Accommodations; All-Inclusive Gourmet Dining (Breakfast, Lunch & Dinner); Roundtrip Speedboat / Seaplane Airport Transfers Included; Complimentary Non-Motorized Water Sports Equipment (Kayak, SUP); Dedicated Island Butler & Resort Concierge Service', 0, 1, 'assets/images/itineraries/maldives-turquoise-atolls/1.webp'),
(8, 'kerala-gods-own-country', 'Kerala Backwaters, Mist Valleys & Ayurvedic Haven', 'God’s Own Country', 'Munnar, Thekkady & Alleppey, India', 'munnar', 5, 4, 'Nature & Wellness', 'DOMESTIC', 'September to May', 'Glide along tranquil palm-fringed backwaters on a private luxury houseboat, breathe crisp tea-scented air in Munnar, and rejuvenate with authentic Ayurvedic wellness.', NULL, 'Overnight Stay on a Premium Air-Conditioned Private Houseboat; Munnar Rolling Tea Plantations, Tea Museum & Mattupetty Dam; Thekkady Periyar Wildlife Sanctuary Lake Boat Safari; Kalaripayattu Martial Arts & Kathakali Traditional Performance; Authentic Rejuvenating Ayurvedic Massage Therapy', 'Luxury Tea Estate Resort & Private Premium Houseboat Accommodations; All Meals Included on the Houseboat (Traditional Kerala Karimeen); Private Dedicated AC Sedan / SUV for the Entire Circuit; Periyar Boat Safari Tickets & Cultural Show Admission; Dedicated Kerala Holiday Manager & Travel Assistance', 0, 1, 'assets/images/itineraries/kerala-gods-own-country/1.webp'),
(9, 'dubai-futuristic-glamour', 'Dubai Futuristic Wonders & Desert Glamour', 'Modern Marvel', 'Dubai, United Arab Emirates', 'dubai', 5, 4, 'Futuristic Luxury', 'INTERNATIONAL', 'October to April', 'Soar to the top of Burj Khalifa, ride luxury yachts in Dubai Marina, embark on adrenaline-charged desert dune safaris, and explore the Museum of the Future.', NULL, 'Burj Khalifa 124th & 125th Floor Observation Deck Priority Access; Red Dunes 4x4 Safari with Camel Rides, Sandboarding & BBQ Gala; Private Dubai Marina Luxury Yacht Cruise with Skyline Views; Museum of the Future & Futuristic Architectural Marvels; Dubai Mall Aquarium, Underwater Zoo & Fountain Symphony', '5-Star Luxury Downtown / Marina Hotel Stay; Daily Lavish International Buffet Breakfasts; Desert Safari Package with VIP Bedouin Camp Seating & Shows; All Fast-Track Attraction Tickets (Burj Khalifa, Museum of the Future); Private Chauffeur Airport Limousine Transfers & City Tours', 0, 1, 'assets/images/itineraries/dubai-futuristic-glamour/1.webp'),
(10, 'udaipur-royal-splendour', 'Udaipur Royal Venice of the East & Heritage Glamour', 'Palace Splendour', 'Udaipur & Kumbhalgarh, Rajasthan, India', 'udaipur', 4, 3, 'Royal Heritage', 'DOMESTIC', 'September to April', 'Relive the golden era of Rajput royalty with Lake Pichola private boat cruises, sprawling marble palaces, vintage car collections, and folk dance galas.', NULL, 'Private Sunset Boat Cruise on Lake Pichola past Jag Mandir; Grand City Palace Complex & Royal Crystal Gallery Tour; Dharohar Folk Dance & Puppet Show at Bagore Ki Haveli; Day Excursion to the Great Wall of India at Kumbhalgarh Fort; Saheliyon Ki Bari Ornamental Gardens & Jagdish Temple', 'Royal Heritage Palace / 5-Star Lake-Facing Hotel Stay; Daily Royal Rajasthani Thali Luncheons & Gourmet Breakfasts; Lake Pichola Private Boat Charter & All Palace Entry Tickets; Private Chauffeur-Driven Luxury Vehicle for All Sightseeing; Dedicated Royal Rajasthan Concierge & Expert Historian Guide', 0, 1, 'assets/images/itineraries/udaipur-royal-splendour/1.webp')
INSERT INTO `itinerary_days` (itinerary_id, day_number, title, description) VALUES
(1, 1, 'Srinagar Arrival, Houseboat Check-In & Sunset Shikara', 'Warm welcome at Srinagar Airport with traditional Kahwa tea. Check in to an intricately hand-carved luxury houseboat on Dal Lake. Enjoy a peaceful sunset Shikara ride across the lotus gardens.'),
(1, 2, 'Gulmarg Meadow of Flowers & Gondola Snow Adventure', 'Drive through apple orchards to Gulmarg. Board the famous Gulmarg Gondola rising up to Apharwat Peak for breathtaking views of Nanga Parbat. Enjoy skiing, sledding, or alpine walks.'),
(1, 3, 'Saffron Fields of Pampore & Journey to Pahalgam', 'Scenic drive to Pahalgam (Valley of Shepherds) along the Lidder River. Stop by the world-famous saffron fields of Pampore and the 9th-century Avantipur temple ruins.'),
(1, 4, 'Pahalgam Betaab Valley, Aru Valley & Baisaran Trek', 'Explore Betaab Valley surrounded by snow peaks and pine forests. Take a horseback excursion through Baisaran (Mini Switzerland) and visit the tranquil meadows of Aru Valley.'),
(1, 5, 'Return to Srinagar & Historic Mughal Gardens Tour', 'Return to Srinagar. Tour the terraced Mughal Gardens: Nishat Bagh (Garden of Bliss), Shalimar Bagh, and Chashme Shahi spring. Visit Shankaracharya Temple overlooking the valley.'),
(1, 6, 'Lal Chowk Souvenirs, Pashmina Shopping & Departure', 'Shop for authentic Kashmiri Pashmina shawls, saffron, walnut woodcrafts, and dry fruits. Private transfer to Srinagar Airport for your departure flight with cherished memories.'),
(2, 1, 'Arrival in Denpasar & Ubud Rainforest Check-In', 'Traditional Balinese floral garland welcome at Ngurah Rai Airport. Transfer to your luxury private pool villa in Ubud. Relax with complimentary herbal tea and scenic valley views.'),
(2, 2, 'Ubud Cultural Circuit, Rice Terraces & Jungle Swing', 'Visit the Sacred Monkey Forest, swing high above the Tegallalang Rice Terraces, and stop by Tegenungan Waterfall. Sample famous Luwak coffee at a traditional plantation.'),
(2, 3, 'Kintamani Volcano Panorama & Sacred Water Temples', 'Witness panoramic views of active Mount Batur volcano and Lake Batur. Experience a purification blessing ritual at the holy spring water temple of Tirta Empul.'),
(2, 4, 'Exhilarating Nusa Penida Island Speedboat Day Tour', 'Sail across the Badung Strait to Nusa Penida. Marvel at the T-Rex shaped Kelingking Clifftop, snorkel in Crystal Bay, and photograph Broken Beach and Angel’s Billabong.'),
(2, 5, 'Seminyak Coastal Vibes, Uluwatu Clifftop & Kecak Dance', 'Transfer to South Bali. Explore trendy Seminyak, visit the clifftop Uluwatu Temple perched 70 meters above crashing waves, and watch the mesmerizing sunset Kecak dance followed by Jimbaran seafood dinner.'),
(2, 6, 'Balinese Spa Rejuvenation & Departure Transfer', 'Indulge in a signature 90-minute Balinese massage session. Visit artisan souvenir markets for authentic woodcarvings and batik before your VIP airport departure.'),
(3, 1, 'Arrival in Goa & Sunset Beachfront Leisure', 'Arrive at Goa Airport / MOPA. Experience a VIP private transfer to your luxury beachfront resort. Spend your afternoon relaxing by the pool or taking a barefoot sunset stroll along the golden sands.'),
(3, 2, 'North Goa Coastal Circuit & Thrilling Water Sports', 'Explore historic Fort Aguada overlooking the Arabian Sea, followed by the vibrant shores of Calangute, Baga, and Anjuna. Enjoy parasailing, jet skiing, and lunch at an iconic beach club.'),
(3, 3, 'South Goa Portuguese Heritage & Mandovi Sunset Cruise', 'Discover the Basilica of Bom Jesus, Se Cathedral, and the charming pastel lanes of Fontainhas in Panjim. In the evening, embark on a private luxury sunset cruise on the Mandovi River with live Goan folk music.'),
(3, 4, 'Dudhsagar Waterfalls & Organic Spice Plantation Luncheon', 'Take a 4x4 jungle jeep safari to the cascading Dudhsagar Waterfalls nestled in the Western Ghats. Tour a heritage spice plantation with an aromatic buffet lunch served on banana leaves.'),
(3, 5, 'Morning Seaside Wellness & Departure', 'Enjoy morning seaside yoga and a lavish breakfast spread. Explore local handicraft markets before a seamless private transfer to the airport for your onward journey.'),
(4, 1, 'Arrival in Phuket & Andaman Sunset Beachfront Check-In', 'Warm welcome at Phuket International Airport and private transfer to your luxury beachfront resort. Savor a chilled tropical cocktail while watching the Andaman sunset over the ocean.'),
(4, 2, 'Phi Phi Islands, Maya Bay & Coral Snorkeling Speedboat Tour', 'Board a premium speedboat to Phi Phi Don and Phi Phi Ley. Swim in the emerald waters of Maya Bay, photograph Viking Cave, and snorkel among colorful marine life at Monkey Beach.'),
(4, 3, 'James Bond Island & Phang Nga Bay Mangrove Canoeing', 'Cruise to mystical Phang Nga Bay. Paddle canoes through limestone cave lagoons (Hong Island) and visit the world-renowned James Bond Island (Koh Tapu).'),
(4, 4, 'Scenic Coastal Drive to Krabi & Ao Nang Beach Leisure', 'Private coastal transfer from Phuket to Krabi past limestone karsts. Check in to your luxury cliffside resort in Ao Nang. Relax with an authentic 60-minute traditional Thai massage.'),
(4, 5, 'Krabi Iconic 4-Islands Speedboat Expedition', 'Explore Koh Poda, Chicken Island, and Tup Island (witness the sandbar phenomenon at low tide). Visit Phra Nang Cave Beach renowned for its rock climbing cliffs and sacred shrine.'),
(4, 6, 'Morning Beach Walk, Souvenir Shopping & Departure', 'Enjoy your final morning beach walk and tropical breakfast. Private transfer to Krabi or Phuket Airport for your return flight with unforgettable memories.'),
(5, 1, 'Arrival at Changi Jewel & Singapore River Cruise', 'Arrive at Singapore Changi Airport. Marvel at the world-famous HSBC Rain Vortex at Jewel. Private luxury transfer to your hotel. In the evening, enjoy a traditional bumboat cruise along the Singapore River.'),
(5, 2, 'City Highlights, Marina Bay Sands & Supertrees', 'Explore Merlion Park, Chinatown, and Little India. Ascend to Marina Bay Sands SkyPark for 360-degree city views. Spend the evening inside Gardens by the Bay watching the dazzling Supertree Grove light and sound show.'),
(5, 3, 'Full-Day Universal Studios & Sentosa Island Fun', 'Board the scenic Sentosa Cable Car. Spend an exhilarating day experiencing thrilling movie-themed rides, shows, and roller coasters at Universal Studios Singapore, followed by Wings of Time night spectacular.'),
(5, 4, 'Orchard Road Shopping & World-First Night Safari', 'Shop at premier luxury malls on Orchard Road or visit the National Orchid Garden. In the evening, take a guided tram tour through the world’s first nocturnal zoo at the Singapore Night Safari.'),
(5, 5, 'Clarke Quay Leisure & VIP Changi Departure', 'Enjoy morning brunch in Clarke Quay or visit the ArtScience Museum. Enjoy private limousine transfer to Changi Airport for duty-free shopping and your flight home.'),
(6, 1, 'Chandigarh / Delhi to Shimla Scenic Mountain Drive', 'Pick-up from Chandigarh or Delhi. Enjoy a picturesque drive through the Shivalik foothills to colonial Shimla. Check in to your luxury resort and take an evening stroll along Mall Road and The Ridge.'),
(6, 2, 'Shimla Heritage Circuit & Kufri Snow Viewpoint', 'Visit Kufri for breathtaking Himalayan panoramic views and horse rides through pine trails. Tour the historic Viceregal Lodge and visit Jakhoo Temple dedicated to Lord Hanuman.'),
(6, 3, 'Scenic River Drive to Manali via Kullu Valley', 'Travel alongside the sparkling Beas River from Shimla to Manali. Stop at Kullu for world-famous Pashmina shawl weaving and optional white-water river rafting before reaching Manali.'),
(6, 4, 'Manali Local Wonders, Ancient Temples & Hot Springs', 'Discover the 500-year-old wooden Hadimba Devi Temple set inside cedar forests. Visit Manu Temple, soak in the natural sulphur hot springs of Vashisht, and explore bohemian Old Manali cafes.'),
(6, 5, 'Solang Valley Thrills & Atal Tunnel Snow Expedition', 'Head to Solang Valley for paragliding and quad biking. Drive through the historic Atal Tunnel (world’s longest highway tunnel above 10,000 ft) into the dramatic snow landscapes of Sissu in Lahaul Valley.'),
(6, 6, 'Morning Pine Forest Stroll & Return Departure', 'Enjoy morning views of snow-dusted peaks over breakfast. Check out and embark on your return drive to Chandigarh Airport/Railway Station for your onward journey.'),
(7, 1, 'Arrival in Malé & Scenic Transfer to Private Island', 'Arrive at Velana International Airport. Board your private speedboat or seaplane soaring over turquoise coral atolls. Check in to your ultra-luxurious overwater villa.'),
(7, 2, 'Overwater Villa Indulgence & House Reef Snorkeling', 'Wake up to panoramic 360-degree ocean views. Step directly from your villa deck into the turquoise lagoon. Join a guided snorkeling tour to discover colorful coral gardens and tropical fish.'),
(7, 3, 'Sandbank Island Picnic & Sunset Dolphin Cruise', 'Take a private dhoni boat to an uninhabited powdery sandbank for a secluded beach picnic. In the evening, set sail on a sunset cruise to watch playful spinner dolphins leap in the ocean glow.'),
(7, 4, 'Spa Wellness & Candlelit Starlit Beach Dinner', 'Rebalance mind and body with a couples’ therapeutic massage at the overwater spa. Conclude your day with a private five-course candlelit dinner served directly on the soft beach sands.'),
(7, 5, 'Sunrise Lagoon Swim & Farewell Island Departure', 'Enjoy a final morning swim in the warm crystal waters and a lavish breakfast overlooking the ocean. Board your return transfer to Malé Airport for your journey home.'),
(8, 1, 'Cochin Arrival & Scenic Mountain Drive to Munnar', 'Arrive at Cochin Airport. Drive through the lush Western Ghats, stopping at Cheeyappara and Valara waterfalls. Check in to your luxury tea plantation resort in misty Munnar.'),
(8, 2, 'Munnar Tea Estates, Eravikulam & Mattupetty Dam', 'Visit Eravikulam National Park, home to the endangered Nilgiri Tahr. Explore the Tata Tea Museum, Echo Point, and Mattupetty Dam with optional speedboating.'),
(8, 3, 'Thekkady Spice Plantations & Periyar Wildlife Safari', 'Scenic drive to Thekkady. Take a guided walking tour of cardamom, pepper, and cinnamon plantations. Enjoy a boat safari in Periyar Tiger Reserve and watch an authentic Kalaripayattu martial arts show.'),
(8, 4, 'Alleppey Backwaters & Private Luxury Houseboat Cruise', 'Drive to Alleppey and board your private luxury houseboat (Kettuvallam). Cruise through emerald canals, paddy fields, and lagoons while savoring freshly prepared Kerala meals by your onboard personal chef.'),
(8, 5, 'Fort Kochi Heritage Walk & Airport Departure', 'Disembark after breakfast. Visit Fort Kochi to see the historic Chinese Fishing Nets, St. Francis Church, and Mattancherry Dutch Palace before your flight departure from Cochin.'),
(9, 1, 'VIP Arrival in Dubai & Marina Skyline Stroll', 'Touch down at Dubai International Airport. Enjoy seamless private limousine transfer to your luxury hotel. Spend your evening exploring the glittering promenades and cafes of Dubai Marina.'),
(9, 2, 'City Landmarks, Museum of the Future & Burj Khalifa', 'Marvel at the Museum of the Future and Dubai Frame. In the afternoon, head to The Dubai Mall and ascend to the 124th floor of Burj Khalifa. Witness the dazzling synchronized Dubai Fountain show.'),
(9, 3, 'Thrilling Desert Safari, Dune Bashing & Arabian Gala', 'Morning at leisure for luxury shopping at Mall of the Emirates. In the afternoon, board a 4x4 Land Cruiser for dune bashing in the Lahbab desert, followed by camel rides, henna painting, Tanoura dance, and BBQ dinner under the stars.'),
(9, 4, 'Miracle Garden, Palm Jumeirah & Private Yacht Cruise', 'Stroll through millions of blooming flowers at Dubai Miracle Garden. Take the Palm Monorail past Atlantis The Palm, and finish with a 2-hour private yacht cruise across Dubai Harbour.'),
(9, 5, 'Gold & Spice Souks, Duty-Free Shopping & Departure', 'Take an Abra boat across Dubai Creek to explore the Gold and Spice Souks. Complete your duty-free shopping before an effortless private airport transfer for your departure flight.'),
(10, 1, 'Royal Welcome in the City of Lakes & Sunset Boat Cruise', 'Arrive in Udaipur with a traditional royal dhol and tikka welcome at your luxury palace resort. In the late afternoon, enjoy an exclusive private boat cruise on Lake Pichola with sunset views over Lake Palace.'),
(10, 2, 'City Palace Grandeur, Crystal Gallery & Cultural Gala', 'Explore the sprawling City Palace complex, towering above Lake Pichola with ornate marble balconies and mirror work. Visit Jagdish Temple, Saheliyon-ki-Bari, and attend the evening Bagore Ki Haveli folk dance show.'),
(10, 3, 'Excursion to Kumbhalgarh Fort & Ranakpur Marble Temples', 'Take a scenic journey through the Aravalli hills to the UNESCO World Heritage Kumbhalgarh Fort, famous for the world’s second-longest continuous wall. Stop at Ranakpur to admire 1,444 uniquely carved marble pillars.'),
(10, 4, 'Vintage Car Collection, Miniature Art & Departure', 'Visit the Maharana’s Vintage & Classic Car Collection. Experience an authentic Rajasthani miniature painting workshop and shopping in Hathi Pol market before your airport drop.');
